def identifier_path(release, identifier):
    encoded = quote(identifier, safe="._-")
    if identifier.isdigit():
        return f"/releases/{release}/sunids/{encoded}"
    if identifier.startswith("d") and len(identifier) >= 6:
        return f"/releases/{release}/sids/{encoded}"
    if SCCS_RE.fullmatch(identifier):
        return f"/releases/{release}/sccs/{encoded}"
    raise ValueError(
        f"cannot infer identifier type for {identifier!r}; use a SID, SUNID, or SCCS"
    )


def fetch_domain(source, release, identifier, include_caveats):
    base = identifier_path(release, identifier)
    lineage = source.get(f"{base}/parents")
    record = {
        "identifier": identifier,
        "release": release,
        "parents": require_lineage(lineage, release, identifier),
    }
    if include_caveats:
        record["annotations"] = source.get(f"{base}/annotations")
        record["homology"] = source.get(f"{base}/homology")
    return record

def fetch_node_caveats(source, release, node):
    sunid = node.get("sunid")
    if not isinstance(sunid, int):
        raise RuntimeError(f"shared ancestor has no public SUNID: {node!r}")
    base = f"/releases/{release}/sunids/{sunid}"
    annotations = source.get(f"{base}/annotations")
    require_release(annotations, release, f"annotations for SUNID {sunid}")
    homology = source.get(f"{base}/homology")
    require_release(homology, release, f"homology for SUNID {sunid}")
    caveats = material_caveats(annotations, homology)
    return {"node": public_node(node), **caveats}


def fetch_ancestor_caveats(source, release, shared):
    checked = []
    material = []
    for node in shared:
        if node_level(node) not in ANCESTOR_CAVEAT_LEVELS:
            continue
        caveats = fetch_node_caveats(source, release, node)
        checked.append(caveats["node"])
        if caveats["annotations"] or caveats["homology"]:
            material.append(caveats)
    return {"checked": checked, "material": material}
